import { describe, it, expect } from 'vitest';
import request from 'supertest';
import { createApp } from '../src/app.js';
import { leadService } from '../src/services/lead.service.js';

describe('Task 8: Google Apps Script Payload Compatibility', () => {
  const app = createApp();

  it('backend should accept the exact payload generated by Code.gs', async () => {
    leadService.resetMockStore();

    // Exact shape generated by Code.gs
    const gasPayload = {
      leads: [
        {
          externalId: 'row_2',
          name: 'Sarah Connor',
          phone: '+1 (555) 321-4321',
          email: 'sarah@skynet.test',
          sourceSheet: 'Inbound Leads 2026',
          consentStatus: 'granted',
          customData: {
            Company: 'Cyberdyne',
            Interest: 'Automation',
            RowNumber: 2,
          },
        },
      ],
    };

    const res = await request(app)
      .post('/api/leads/webhook')
      .set('X-Webhook-Secret', 'dev-webhook-secret-change-in-prod')
      .send(gasPayload);

    expect(res.status).toBe(200);
    expect(res.body.summary.ingested).toBe(1);
    expect(res.body.leads[0].externalId).toBe('row_2');
    expect(res.body.leads[0].phone).toBe('+15553214321');
  });
});
